// Generates packages/shared/src/entities.generated.ts from packages/db/migrations/*.sql
// Run: npm run gen:zod. Do not edit the output by hand.
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const migDir = join(root, 'packages/db/migrations');
const sql = readdirSync(migDir).filter((f) => f.endsWith('.sql')).sort()
  .map((f) => readFileSync(join(migDir, f), 'utf8')).join('\n')
  .replace(/--[^\n]*/g, '');

function splitTop(body) {
  const out = []; let depth = 0, cur = '', q = false;
  for (const ch of body) {
    if (ch === "'") q = !q;
    if (!q && ch === '(') depth++;
    if (!q && ch === ')') depth--;
    if (!q && depth === 0 && ch === ',') { out.push(cur.trim()); cur = ''; continue; }
    cur += ch;
  }
  if (cur.trim()) out.push(cur.trim());
  return out;
}
const pascal = (s) => s.split('_').map((p) => p[0].toUpperCase() + p.slice(1)).join('');
const camel = (s) => { const p = pascal(s); return p[0].toLowerCase() + p.slice(1); };

function zodType(type, col, checks) {
  const t = type.toLowerCase();
  const en = checks.find((c) => new RegExp(`^\\(?\\s*${col}\\s+IN\\s*\\(`, 'i').test(c));
  if (en) {
    const vals = [...en.matchAll(/'([^']*)'/g)].map((m) => m[1]);
    if (vals.length) return `z.enum([${vals.map((v) => JSON.stringify(v)).join(', ')}])`;
  }
  if (t.endsWith('[]')) return `z.array(${zodType(t.slice(0, -2), '__', [])})`;
  if (t === 'uuid') return 'z.string().uuid()';
  if (t === 'bigint' || t === 'bigserial') return 'z.number().int()'; // kopecks; safe below 2^53
  if (t === 'int' || t === 'integer' || t === 'smallint' || t === 'serial') return 'z.number().int()';
  if (t.startsWith('numeric') || t === 'real' || t.startsWith('double')) return 'z.number()';
  if (t === 'boolean' || t === 'bool') return 'z.boolean()';
  if (t === 'timestamptz' || t === 'timestamp') return 'z.string().datetime({ offset: true })';
  if (t === 'date') return 'z.string().date()';
  if (t === 'jsonb' || t === 'json') return 'z.unknown()';
  if (t === 'bytea') return 'z.instanceof(Uint8Array)';
  if (t === 'inet') return 'z.string().ip()';
  if (t === 'tstzrange') return 'z.object({ from: z.string().datetime({ offset: true }), to: z.string().datetime({ offset: true }) })';
  const m = t.match(/^(?:varchar|char)\((\d+)\)$/);
  if (m) return t.startsWith('char') ? `z.string().length(${m[1]})` : `z.string().max(${m[1]})`;
  return 'z.string()';
}

const tables = [];
const re = /CREATE TABLE\s+(?:IF NOT EXISTS\s+)?("?\w+"?)\s*\(([\s\S]*?)\)\s*(?:PARTITION BY[^;]*)?;/gi;
let m;
while ((m = re.exec(sql))) {
  const name = m[1].replace(/"/g, '');
  if (/PARTITION OF/i.test(m[0])) continue;
  const parts = splitTop(m[2]);
  const checks = parts.filter((p) => /^CHECK/i.test(p)).map((p) => p.replace(/^CHECK\s*/i, ''));
  const cols = [];
  for (const p of parts) {
    if (/^(CHECK|UNIQUE|PRIMARY\s+KEY|EXCLUDE|CONSTRAINT|FOREIGN)/i.test(p)) continue;
    const cm = p.match(/^("?\w+"?)\s+([\w]+(?:\s+precision)?(?:\([\d,\s]+\))?(?:\[\])?)([\s\S]*)$/i);
    if (!cm) continue;
    const col = cm[1].replace(/"/g, ''); const rest = cm[3];
    const inl = [...rest.matchAll(/CHECK\s*(\([\s\S]*\))/gi)].map((x) => x[1].replace(/^\(|\)$/g, ''));
    const z = zodType(cm[2], col, [...inl, ...checks]);
    const nullable = !/NOT NULL|PRIMARY KEY/i.test(rest) && !/GENERATED/i.test(rest);
    cols.push(`  ${col}: ${z}${nullable ? '.nullable()' : ''},`);
  }
  tables.push({ name, cols });
}
if (tables.length < 10) throw new Error(`parsed only ${tables.length} tables`);

let out = `// AUTO-GENERATED by scripts/gen-zod.mjs from packages/db/migrations. Do not edit.\n` +
  `// Row shapes (snake_case, as stored in PostgreSQL). Money = integer kopecks.\nimport { z } from 'zod';\n\n`;
for (const t of tables) {
  out += `export const ${camel(t.name)}Schema = z.object({\n${t.cols.join('\n')}\n});\n` +
    `export type ${pascal(t.name)} = z.infer<typeof ${camel(t.name)}Schema>;\n\n`;
}
out += `export const entitySchemas = {\n${tables.map((t) => `  ${t.name}: ${camel(t.name)}Schema,`).join('\n')}\n} as const;\n` +
  `export type EntityName = keyof typeof entitySchemas;\n`;
writeFileSync(join(root, 'packages/shared/src/entities.generated.ts'), out);
console.log(`generated ${tables.length} entity schemas`);
